+            logger.info("Finished setting [upgrade_mode] for feature name [{}]", featureName());
+            isRunning.set(false);
+            listener.onResponse(r);
+        }, e -> {
+            logger.info("Failed to set [upgrade_mode] for feature name [{}]", featureName());
+            isRunning.set(false);
+            listener.onFailure(e);
+        });
